#include <string.h>

size_t RegisterJPEGImage(void) {
    size_t size = 0;
    char version[] = "v6.0.0";
    char description[] = "JPEG (Joint Photographic Experts Group) Image";

    struct {
        const char *format;
        void (*decoder)();
        void (*encoder)();
        int thread_support;
        const char *mime_type;
    } entries[] = {
        {"JPE", NULL, NULL, 1, "image/jpeg"},
        {"JPEG", NULL, NULL, 1, "image/jpeg"},
        {"JPG", NULL, NULL, 1, "image/jpeg"},
        {"JPS", NULL, NULL, 1, "image/jpeg"},
        {"PJPEG", NULL, NULL, 1, "image/jpeg"},
    };

    for (size_t i = 0; i < sizeof(entries) / sizeof(entries[0]); ++i) {
        MagickInfo *magick_info = SetMagickInfo(entries[i].format);
        if (magick_info != NULL) {
            magick_info->decoder = entries[i].decoder;
            magick_info->encoder = entries[i].encoder;
            magick_info->thread_support = entries[i].thread_support;
            magick_info->mime_type = (char *) AcquireString(entries[i].mime_type);
            RegisterMagickInfo(magick_info);
            size += sizeof(magick_info);
        }
    }

    return size;
}
